main_prompt_template:
Analyze this hockey drill/play query and extract components needed for a diagram.

QUERY: "{query}"
{clarifications}

Your task is to analyze this query with hockey expertise and provide a structured JSON response.

{instructions}

{output_format}

{hockey_knowledge}

Apply your hockey expertise to provide a complete, realistic analysis.

output_format:
Output a JSON object with this EXACT structure:
{
    "original_query": "the original query",
    "explicit_info": {
        "situation": "faceoff/drill/play/practice",
        "zone": "offensive/defensive/neutral if mentioned",
        "key_actions": ["list of mentioned actions"],
        "faceoff_location": "right dot/left dot/center ice if applicable"
    },
    "components_with_assumptions": {
        "rink": {
            "view": "full/half/offensive/defensive/neutral",
            "assumption": "reasoning for this choice",
            "confidence": 0.0-1.0
        },
        "players": [
            {
                "id": "C/LW/RW/LD/RD for home, OC/OW1/OW2/OD1/OD2/G for away",
                "type": "center/winger/defense/goalie",
                "team": "home/away",
                "position_desc": "natural language position description",
                "assumption": "why this player is needed",
                "confidence": 0.0-1.0
            }
        ],
        "movements": [
            {
                "id": "m1/m2/m3 etc in sequence",
                "type": "pass/shot/skate/carry/backpass/drop_pass",
                "desc": "movement description",
                "from_player": "player ID who starts the movement",
                "to_player": "player ID who receives (for passes ONLY - identify specific player)",
                "to_area": "target area description (for all movements)",
                "assumption": "reasoning for this movement",
                "confidence": 0.0-1.0
            }
        ],
        "zones": [],
        "annotations": [
            {
                "text": "title or label text",
                "position_desc": "where to place it (title/subtitle/note)",
                "assumption": "why this annotation",
                "confidence": 0.0-1.0
            }
        ],
        "equipment": [
            {
                "id": "eq1/eq2/etc sequential",
                "type": "cone/pylon/puck/net/tire/stick",
                "position_desc": "natural language position (e.g., 'along blue line', 'in slot area')",
                "count": 1,
                "color": "orange/yellow/blue/red/white/black",
                "purpose": "what the equipment is for",
                "assumption": "why this equipment is needed",
                "confidence": 0.0-1.0
            }
        ],
        "coaches": [
            {
                "id": "COACH1/COACH2/etc sequential",
                "position_desc": "natural language position (e.g., 'at center ice', 'behind goal line', 'on bench')",
                "role": "observer/instructor/demonstration/safety",
                "assumption": "why this coach is positioned here",
                "confidence": 0.0-1.0
            }
        ]
    },
    "questions_for_user": [
        {
            "question": "question text",
            "key": "parameter_key",
            "options": ["option1", "option2"],
            "critical": true/false,
            "confidence": 0.0-1.0
        }
    ],
    "metadata": {
        "type": "drill/play/practice",
        "phase": "offensive/defensive/neutral/transition",
        "key_players": ["list of key player IDs involved in the action"]
    }
}

